      { q: { es: '¿Por qué el waveshaping es "dinámico"?', en: 'Why is waveshaping "dynamic"?', de: 'Warum ist Waveshaping „dynamisch"?', ja: 'ウェーブシェイピングが「ダイナミック」な理由は？' }, o: { es: ['Porque usa un LFO', 'Porque los armónicos dependen del nivel de entrada', 'Porque cambia la altura', 'No lo es'], en: ['Because it uses an LFO', 'Because harmonics depend on input level', 'Because it changes pitch', 'It isn\'t'], de: ['Wegen eines LFO', 'Weil Obertöne vom Eingangspegel abhängen', 'Weil es die Tonhöhe ändert', 'Ist es nicht'], ja: ['LFOを使うから', '倍音が入力レベルに依存するから', '音高が変わるから', 'ダイナミックではない'] }, c: 1, x: { es: 'Más nivel recorre más la curva no lineal → más armónicos.', en: 'More level traverses more of the non-linear curve → more harmonics.', de: 'Mehr Pegel durchläuft mehr Kurve → mehr Obertöne.', ja: 'レベルが高いほど非線形カーブを広くたどる→倍音が増える。' } },
      { q: { es: '¿Qué agrega un rectificador / curva asimétrica?', en: 'What does a rectifier / asymmetric curve add?', de: 'Was fügt ein Gleichrichter / eine asymmetrische Kurve hinzu?', ja: '整流／非対称カーブが加えるものは？' }, o: { es: ['Solo armónicos impares', 'Armónicos pares (y DC)', 'Nada', 'Ruido rosa'], en: ['Odd harmonics only', 'Even harmonics (and DC)', 'Nothing', 'Pink noise'], de: ['Nur ungerade Obertöne', 'Gerade Obertöne (und DC)', 'Nichts', 'Rosa Rauschen'], ja: ['奇数倍音のみ', '偶数倍音（と直流）', '何も', 'ピンクノイズ'] }, c: 1, x: { es: 'La asimetría rompe la simetría de media onda, generando pares.', en: 'Asymmetry breaks half-wave symmetry, generating even harmonics.', de: 'Asymmetrie bricht die Halbwellensymmetrie → gerade Obertöne.', ja: '非対称性が半波対称性を崩し、偶数倍音を生みます。' } },
      { q: { es: '¿Qué combina una low-pass gate?', en: 'What does a low-pass gate combine?', de: 'Was kombiniert ein Low-Pass-Gate?', ja: 'ローパスゲートが組み合わせるものは？' }, o: { es: ['Oscilador y LFO', 'Filtro pasa bajos y VCA', 'Delay y reverb', 'Dos osciladores'], en: ['Oscillator and LFO', 'Low-pass filter and VCA', 'Delay and reverb', 'Two oscillators'], de: ['Oszillator und LFO', 'Tiefpass und VCA', 'Delay und Hall', 'Zwei Oszillatoren'], ja: ['オシレーターとLFO', 'ローパスフィルターとVCA', 'ディレイとリバーブ', '2つのオシレーター'] }, c: 1, x: { es: 'Brillo y volumen se mueven juntos, como un objeto acústico.', en: 'Brightness and level move together, like an acoustic object.', de: 'Helligkeit und Pegel bewegen sich gemeinsam.', ja: '明るさと音量が一緒に動き、アコースティックな物体のよう。' } },
      { q: { es: 'El polinomio T3 aplicado a una senoidal de amplitud 1 produce…', en: 'T3 applied to a unit-amplitude sine produces…', de: 'T3 auf einen Sinus mit Amplitude 1 ergibt…', ja: '振幅1のサイン波にT3を適用すると…' }, o: { es: ['La fundamental', 'El 3er armónico', 'Ruido', 'Una cuadrada'], en: ['The fundamental', 'The 3rd harmonic', 'Noise', 'A square'], de: ['Den Grundton', 'Den 3. Oberton', 'Rauschen', 'Ein Rechteck'], ja: ['基音', '第3倍音', 'ノイズ', '矩形波'] }, c: 1, x: { es: 'T3(cos θ) = cos(3θ).', en: 'T3(cos θ) = cos(3θ).', de: 'T3(cos θ) = cos(3θ).', ja: 'T3(cos θ)＝cos(3θ)。' } }
